export type ModuleMessageKey = keyof typeof messages;
export const MODULE_MESSAGE_KEYS = Object.keys(messages) as ModuleMessageKey[];

export function apiModuleMessage(locale: unknown, key: ModuleMessageKey): string {
  return messages[key][API_LOCALES.indexOf(apiLocale(locale))] ?? messages[key][1];
}

export function localizeGitServiceMessage(locale: unknown, source: string): string {
  const keys = {
    "No es un repositorio Git": "notGitRepo",
    "Nombre de rama inválido": "invalidBranchName",
    "El mensaje del commit es obligatorio": "gitCommitMessageRequired",
    "No hay rama activa": "gitNoActiveBranch",
    "No se pudo consultar origin": "gitOriginUnavailable",
    "No se pudo comparar HEAD con origin": "gitCompareFailed",
    "URL inválida": "gitInvalidUrl",
    "URL de repositorio no válida (usa https://, ssh:// o git@host:…)": "gitInvalidRepoUrl",
    "Destino fuera de las rutas permitidas": "gitDestOutsideAllowed",
    "Destino inválido": "gitInvalidDest",
  } as const;
  const key = keys[source as keyof typeof keys];
  if (key) return apiModuleMessage(locale, key);
  const branch = /^La rama actual no sigue origin\/(.+)$/.exec(source)?.[1];
  if (branch) return apiModuleMessage(locale, "gitBranchNotTracking").replace("{branch}", () => branch);
  return source;
}

export function localizeRepoCloneStatus(locale: unknown, source: string): string {
  const mismatch = /^La rama actual \((.*)\) difiere de la registrada \((.*)\)$/.exec(source);
  if (mismatch) return apiModuleMessage(locale, "repoBranchMismatch")
    .replace("{current}", () => mismatch[1] ?? "")
    .replace("{saved}", () => mismatch[2] ?? "");
  return localizeGitServiceMessage(locale, source);
}

export function localizeOpenClawTestMessage(locale: unknown, source: string): string {
  const keys = {
    "Falta la API key de OpenClaw": "openclawApiKeyMissing",
    "El endpoint no es una URL pública válida": "openclawInvalidEndpoint",
    "Conexión exitosa": "openclawConnectionOk",
    "API key rechazada por el servidor": "openclawApiKeyRejected",
    "No se pudo contactar OpenClaw": "openclawContactFailed",
  } as const;
  const key = keys[source as keyof typeof keys];
  if (key) return apiModuleMessage(locale, key);
  const match = source.match(/^OpenClaw respondió con HTTP (\d{3})$/);
  return match ? apiModuleMessage(locale, "openclawHttpStatus").replace("{status}", match[1] ?? "") : source;
}

export function localizeCloudflareTokenMessage(locale: unknown, source: string): string {
  if (source === "No hay un API token de Cloudflare configurado" || source === "No hay un token de API de Cloudflare configurado") return apiModuleMessage(locale, "cloudflareTokenMissing");
  if (source === "Token válido y activo") return apiModuleMessage(locale, "cloudflareTokenActive");
  const status = /^El token existe pero su estado es "(.*)"$/.exec(source)?.[1];
  return status === undefined ? source : apiModuleMessage(locale, "cloudflareTokenState").replace("{status}", () => status);
}

export function localizeImageOptimMessage(locale: unknown, source: string): string {
  const keys = {
    "Instala cwebp o ImageMagick para convertir a WebP": "imageWebpToolMissing",
    "Instala ImageMagick (o jpegoptim/optipng) para comprimir": "imageCompressToolMissing",
    "Instala ImageMagick para redimensionar": "imageResizeToolMissing",
    "Instala ImageMagick para generar variantes responsive": "imageResponsiveToolMissing",
    "No se generó ninguna variante": "imageNoVariants",
    "Conversión fallida": "imageConversionFailed",
    "Compresión fallida": "imageCompressionFailed",
    "Redimensión fallida": "imageResizeFailed",
  } as const;
  const key = keys[source as keyof typeof keys];
  return key ? apiModuleMessage(locale, key) : source;
}

/** The team service is shared with agent tools; translate its known failures at the HTTP boundary. */
export function localizeTeamTaskFailure(locale: unknown, source: string): string {
  if (source === "No se pudieron resolver los proyectos del agente.") return apiModuleMessage(locale, "teamProjectsResolveFailed");
  if (source === "No se pudo registrar la tarea del equipo.") return apiModuleMessage(locale, "teamTaskRegisterFailed");
  const project = /^El proyecto "(.*)" no pertenece al agente "(.*)"\.$/.exec(source);
  if (project) return apiModuleMessage(locale, "teamProjectNotOwned")
    .replace("{project}", () => project[1] ?? "")
    .replace("{agent}", () => project[2] ?? "");
  const active = /^Límite de (\d+) tareas activas por conversación alcanzado;/.exec(source);
  if (active) return apiModuleMessage(locale, "teamActiveLimit").replace("{count}", () => active[1] ?? "");
  const budget = /^Presupuesto del plan agotado \((\d+) de (\d+) tokens; plan ([^)]+)\);/.exec(source);
  if (budget) return apiModuleMessage(locale, "teamBudgetExhausted")
    .replace("{spent}", () => budget[1] ?? "")
    .replace("{budget}", () => budget[2] ?? "")
    .replace("{planId}", () => budget[3] ?? "");
  return apiModuleMessage(locale, "teamAssignmentFailed");
}
